const specRegex = /(?:^|(?<=[^@\w]))@([\w-]+)/g;
const implRegex = /(?:^|(?<=\W))@([\w-]+)/g;

const tests = [
  { input: '@alice', expected: ['alice'] },
  { input: 'hello @alice', expected: ['alice'] },
  { input: 'foo@bar', expected: [] },
  { input: '@@alice', expected: [] },  // double @ should NOT match
  { input: '@alice @bob', expected: ['alice', 'bob'] },
  { input: '@alice @alice', expected: ['alice'] },  // duplicate
  { input: 'test@@alice end', expected: [] },  // double @ in middle
];

for (const t of tests) {
  const specMatches = [...t.input.matchAll(specRegex)].map(m => m[1]);
  const implMatches = [...t.input.matchAll(implRegex)].map(m => m[1]);
  console.log(JSON.stringify({ input: t.input, expected: t.expected, spec: specMatches, impl: implMatches, match: JSON.stringify(specMatches) === JSON.stringify(t.expected) ? 'SPEC_OK' : 'SPEC_FAIL', deviates: JSON.stringify(specMatches) !== JSON.stringify(implMatches) ? 'REGEX_DEVIATION' : 'SAME' }));
}
"

