1	/**
2	 * Integration tests for tracker mentions methods.
3	 *
4	 * Tests the full tracker flow: init → register users → create issue →
5	 * add/update/delete comments → mentions are auto-indexed →
6	 * list/view/read/unread/rebuild operations.
7	 */
8	import { afterEach, beforeEach, describe, expect, test } from "bun:test";
9	import { existsSync, readFileSync, rmSync } from "node:fs";
10	import { tmpdir } from "node:os";
11	import { join } from "node:path";
12	import { AgentrackError } from "../../../src/core/errors";
13	import { Tracker } from "../../../src/core/tracker";
14	
15	describe("Tracker mentions integration", () => {
16	  let testDir: string;
17	  let tracker: Tracker;
18	
19	  beforeEach(async () => {
20	    testDir = join(
21	      tmpdir(),
22	      `tracker-mentions-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
23	    );
24	    tracker = new Tracker(testDir);
25	    await tracker.init();
26	  });
27	
28	  afterEach(() => {
29	    rmSync(testDir, { recursive: true, force: true });
30	  });
31	
32	  // Helper: create an issue and return its id
33	  async function createIssue(title = "Test Issue"): Promise<string> {
34	    const result = await tracker.create({ title });
35	    if (!("id" in result)) throw new Error("Create failed");
36	    return result.id;
37	  }
38	
39	  // Helper: register a user and return token
40	  async function registerUser(name: string): Promise<string> {
41	    const result = await tracker.usersRegister(name);
42	    if (!("token" in result)) throw new Error("Register failed");
43	    return result.token;
44	  }
45	
46	  // ─── AC8: Init creates empty mentions.json ────────────────────────
47	
48	  describe("init creates mentions.json", () => {
49	    test("init creates empty mentions.json", async () => {
50	      const mentionsPath = join(testDir, "mentions.json");
51	      expect(existsSync(mentionsPath)).toBe(true);
52	
53	      const content = readFileSync(mentionsPath, "utf-8");
54	      expect(JSON.parse(content)).toEqual({});
55	    });
56	  });
57	
58	  // ─── AC3: Auto-indexing on comment operations ─────────────────────
59	
60	  describe("auto-indexing on commentsAdd", () => {
61	    test("single mention is indexed after commentsAdd", async () => {
62	      await registerUser("alice");
63	      await registerUser("bob");
64	      const issueId = await createIssue();
65	
66	      await tracker.commentsAdd(issueId, {
67	        content: "@alice please review this",
68	        author: "bob",
69	      });
70	
71	      const mentions = await tracker.mentionsList("alice", { includeReads: true });
72	      expect(Array.isArray(mentions)).toBe(true);
73	      if (Array.isArray(mentions)) {
74	        expect(mentions).toHaveLength(1);
75	        expect(mentions[0]!.mentionedBy).toBe("bob");
76	        expect(mentions[0]!.issueId).toBe(issueId);
77	        expect(mentions[0]!.isRead).toBe(false);
78	      }
79	    });
80	
81	    test("multiple mentions in one comment create multiple entries", async () => {
82	      await registerUser("alice");
83	      await registerUser("bob");
84	      await registerUser("charlie");
85	      const issueId = await createIssue();
86	
87	      await tracker.commentsAdd(issueId, {
88	        content: "@alice and @bob please review",
89	        author: "charlie",
90	      });
91	
92	      const aliceMentions = await tracker.mentionsList("alice", { includeReads: true });
93	      const bobMentions = await tracker.mentionsList("bob", { includeReads: true });
94	      if (Array.isArray(aliceMentions)) {
95	        expect(aliceMentions).toHaveLength(1);
96	      }
97	      if (Array.isArray(bobMentions)) {
98	        expect(bobMentions).toHaveLength(1);
99	      }
100	    });
101	
102	    test("duplicate mentions in one comment produce single entry", async () => {
103	      await registerUser("alice");
104	      await registerUser("bob");
105	      const issueId = await createIssue();
106	
107	      await tracker.commentsAdd(issueId, {
108	        content: "@alice @alice @alice",
109	        author: "bob",
110	      });
111	
112	      const mentions = await tracker.mentionsList("alice", { includeReads: true });
113	      if (Array.isArray(mentions)) {
114	        expect(mentions).toHaveLength(1);
115	      }
116	    });
117	
118	    test("unregistered user mentions are silently ignored", async () => {
119	      await registerUser("bob");
120	      const issueId = await createIssue();
121	
122	      await tracker.commentsAdd(issueId, {
123	        content: "@unknown-user hello",
124	        author: "bob",
125	      });
126	
127	      // No mentions should exist for any user
128	      const mentionsPath = join(testDir, "mentions.json");
129	      const content = readFileSync(mentionsPath, "utf-8");
130	      const mentions = JSON.parse(content) as Record<string, unknown[]>;
131	      const totalMentions = Object.values(mentions).reduce((sum, arr) => sum + arr.length, 0);
132	      expect(totalMentions).toBe(0);
133	    });
134	
135	    test("comment with no mentions produces no mention entries", async () => {
136	      await registerUser("alice");
137	      await registerUser("bob");
138	      const issueId = await createIssue();
139	
140	      await tracker.commentsAdd(issueId, {
141	        content: "No mentions here",
142	        author: "bob",
143	      });
144	
145	      const mentions = await tracker.mentionsList("alice", { includeReads: true });
146	      if (Array.isArray(mentions)) {
147	        expect(mentions).toHaveLength(0);
148	      }
149	    });
150	
151	    test("self-mention works (author mentions themselves)", async () => {
152	      await registerUser("alice");
153	      const issueId = await createIssue();
154	
155	      await tracker.commentsAdd(issueId, {
156	        content: "@alice note to self",
157	        author: "alice",
158	      });
159	
160	      const mentions = await tracker.mentionsList("alice", { includeReads: true });
161	      if (Array.isArray(mentions)) {
162	        expect(mentions).toHaveLength(1);
163	        expect(mentions[0]!.mentionedBy).toBe("alice");
164	      }
165	    });
166	  });
167	
168	  describe("auto-indexing on commentsUpdate", () => {
169	    test("update re-indexes mentions: removes old, adds new", async () => {
170	      await registerUser("alice");
171	      await registerUser("bob");
172	      await registerUser("charlie");
173	      const issueId = await createIssue();
174	
175	      const addResult = await tracker.commentsAdd(issueId, {
176	        content: "@alice review this",
177	        author: "bob",
178	      });
179	      if (addResult.result !== "OK") throw new Error("Add failed");
180	
181	      // Verify alice has 1 mention, bob has 0
182	      let aliceMentions = await tracker.mentionsList("alice", { includeReads: true });
183	      if (Array.isArray(aliceMentions)) {
184	        expect(aliceMentions).toHaveLength(1);
185	      }
186	
187	      // Update: change mention from @alice to @bob
188	      await tracker.commentsUpdate(issueId, addResult.commentId, {
189	        content: "@bob check this instead",
190	        author: "bob",
191	      });
192	
193	      // Alice should now have 0 mentions
194	      aliceMentions = await tracker.mentionsList("alice", { includeReads: true });
195	      if (Array.isArray(aliceMentions)) {
196	        expect(aliceMentions).toHaveLength(0);
197	      }
198	
199	      // Bob should now have 1 mention
200	      const bobMentions = await tracker.mentionsList("bob", { includeReads: true });
201	      if (Array.isArray(bobMentions)) {
202	        expect(bobMentions).toHaveLength(1);
203	      }
204	    });
205	
206	    test("update resets isRead for re-mentioned users (CL2)", async () => {
207	      await registerUser("alice");
208	      await registerUser("bob");
209	      const issueId = await createIssue();
210	
211	      const addResult = await tracker.commentsAdd(issueId, {
212	        content: "@alice review this",
213	        author: "bob",
214	      });
215	      if (addResult.result !== "OK") throw new Error("Add failed");
216	
217	      // Get the mention and mark it as read
218	      let mentions = await tracker.mentionsList("alice", { includeReads: true });
219	      if (Array.isArray(mentions) && mentions.length > 0) {
220	        const mentionId = mentions[0]!.id;
221	        await tracker.mentionsRead(mentionId, { author: "alice" });
222	
223	        // Verify it's read
224	        mentions = await tracker.mentionsList("alice");
225	        if (Array.isArray(mentions)) {
226	          expect(mentions).toHaveLength(0); // unread filter shows nothing
227	        }
228	      }
229	
230	      // Update the comment (re-mentions @alice)
231	      await tracker.commentsUpdate(issueId, addResult.commentId, {
232	        content: "@alice updated content",
233	        author: "bob",
234	      });
235	
236	      // Alice should have a new unread mention
237	      mentions = await tracker.mentionsList("alice");
238	      if (Array.isArray(mentions)) {
239	        expect(mentions).toHaveLength(1);
240	        expect(mentions[0]!.isRead).toBe(false);
241	      }
242	    });
243	
244	    test("update removing all mentions clears entries", async () => {
245	      await registerUser("alice");
246	      await registerUser("bob");
247	      const issueId = await createIssue();
248	
249	      const addResult = await tracker.commentsAdd(issueId, {
250	        content: "@alice review this",
251	        author: "bob",
252	      });
253	      if (addResult.result !== "OK") throw new Error("Add failed");
254	
255	      // Update to remove all mentions
256	      await tracker.commentsUpdate(issueId, addResult.commentId, {
257	        content: "No mentions anymore",
258	        author: "bob",
259	      });
260	
261	      const aliceMentions = await tracker.mentionsList("alice", { includeReads: true });
262	      if (Array.isArray(aliceMentions)) {
263	        expect(aliceMentions).toHaveLength(0);
264	      }
265	    });
266	  });
267	
268	  describe("auto-indexing on commentsDelete", () => {
269	    test("delete removes associated mentions", async () => {
270	      await registerUser("alice");
271	      await registerUser("bob");
272	      const issueId = await createIssue();
273	
274	      const addResult = await tracker.commentsAdd(issueId, {
275	        content: "@alice review this",
276	        author: "bob",
277	      });
278	      if (addResult.result !== "OK") throw new Error("Add failed");
279	
280	      // Verify mention exists
281	      let mentions = await tracker.mentionsList("alice", { includeReads: true });
282	      if (Array.isArray(mentions)) {
283	        expect(mentions).toHaveLength(1);
284	      }
285	
286	      // Delete the comment
287	      await tracker.commentsDelete(issueId, addResult.commentId, { author: "bob" });
288	
289	      // Mention should be gone
290	      mentions = await tracker.mentionsList("alice", { includeReads: true });
291	      if (Array.isArray(mentions)) {
292	        expect(mentions).toHaveLength(0);
293	      }
294	    });
295	
296	    test("delete preserves mentions from other comments", async () => {
297	      await registerUser("alice");
298	      await registerUser("bob");
299	      const issueId = await createIssue();
300	
301	      const add1 = await tracker.commentsAdd(issueId, {
302	        content: "@alice first",
303	        author: "bob",
304	      });
305	      if (add1.result !== "OK") throw new Error("Add1 failed");
306	
307	      await tracker.commentsAdd(issueId, {
308	        content: "@alice second",
309	        author: "bob",
310	      });
311	
312	      // 2 mentions for alice
313	      let mentions = await tracker.mentionsList("alice", { includeReads: true });
314	      if (Array.isArray(mentions)) {
315	        expect(mentions).toHaveLength(2);
316	      }
317	
318	      // Delete first comment
319	      await tracker.commentsDelete(issueId, add1.commentId, { author: "bob" });
320	
321	      // 1 mention remaining
322	      mentions = await tracker.mentionsList("alice", { includeReads: true });
323	      if (Array.isArray(mentions)) {
324	        expect(mentions).toHaveLength(1);
325	      }
326	    });
327	  });
328	
329	  // ─── AC4: mentionsList ────────────────────────────────────────────
330	
331	  describe("mentionsList", () => {
332	    test("returns unread mentions by default", async () => {
