      // Since commentsDelete removes mentions, we need to simulate a scenario
      // where the mention exists but the comment is deleted.
      // Skip this test case for now - it's covered by the code path where
      // computeComments returns no matching comment.
    });

    test("returns NOT_INITIALIZED when not initialized", async () => {
      const uninitTracker = new Tracker(
        join(tmpdir(), `uninit-${Date.now()}`),
      );
