      // First mark as read
      await tracker.mentionsRead(mentions[0]!.id, { author: "alice" });

      // Then mark as unread
      const result = await tracker.mentionsUnread(mentions[0]!.id, { author: "alice" });
      expect(result).toEqual({ result: "OK" });

      // Verify it's now unread
      const updated = await tracker.mentionsList("alice");
      if (Array.isArray(updated)) {
        expect(updated).toHaveLength(1);
        expect(updated[0]!.isRead).toBe(false);
