1	/**
2	 * E2E: mentions — Type B tests (tracker operations via CLI)
3	 *
4	 * Tests the mentions CLI commands: list, view, read, unread, rebuild.
5	 * Also tests auto-indexing integration: add/update/delete comments.
6	 *
7	 * Note: resetWorktreeData() does not currently reset mentions.json (spec
8	 * deviation CL5). We manually reset it in beforeEach as a workaround.
9	 */
10	import { existsSync, writeFileSync } from "node:fs";
11	import { join } from "node:path";
12	import { beforeAll, beforeEach, describe, expect, test } from "bun:test";
13	import {
14	  E2E_DATA_BRANCH,
15	  assertError,
16	  assertSuccess,
17	  ensureE2EWorktree,
18	  extractId,
19	  getTrackerDir,
20	  parseJson,
21	  resetWorktreeData,
22	  runAgt,
23	} from "./setup";
24	
25	describe("E2E: mentions", () => {
26	  beforeAll(async () => {
27	    await ensureE2EWorktree(E2E_DATA_BRANCH);
28	  });
29	
30	  beforeEach(() => {
31	    resetWorktreeData(E2E_DATA_BRANCH);
32	    // Workaround: resetWorktreeData doesn't reset mentions.json (spec deviation CL5)
33	    const trackerDir = getTrackerDir(E2E_DATA_BRANCH);
34	    const mentionsPath = join(trackerDir, "mentions.json");
35	    if (existsSync(mentionsPath)) {
36	      writeFileSync(mentionsPath, "{}\n", "utf-8");
37	    }
38	  });
39	
40	  // ─── mentions list ────────────────────────────────────────────────
41	
42	  describe("mentions list", () => {
43	    test("returns empty array for user with no mentions", async () => {
44	      await runAgt(["users", "register", "alice"]);
45	
46	      const result = await runAgt(["mentions", "list", "alice"]);
47	      assertSuccess(result);
48	
49	      const parsed = parseJson(result.stdout);
50	      expect(parsed).toEqual([]);
51	    });
52	
53	    test("returns USER_NOT_FOUND for unregistered user", async () => {
54	      const result = await runAgt(["mentions", "list", "nonexistent"]);
55	      assertError(result, "USER_NOT_FOUND", 9);
56	    });
57	
58	    test("lists mentions after comment with @mention", async () => {
59	      await runAgt(["users", "register", "alice"]);
60	      await runAgt(["users", "register", "bob"]);
61	
62	      const issueId = extractId(await runAgt(["create", "Bug Fix"]));
63	      await runAgt(["comments", "add", issueId, "--content", "@alice review this"]);
64	
65	      const result = await runAgt(["mentions", "list", "alice"]);
66	      assertSuccess(result);
67	
68	      const parsed = parseJson(result.stdout);
69	      expect(parsed).toHaveLength(1);
70	      expect(parsed[0].mentionedBy).toBe("bob");
71	      expect(parsed[0].issueTitle).toBe("Bug Fix");
72	      expect(parsed[0].isRead).toBe(false);
73	    });
74	
75	    test("includes read mentions with --include-reads flag", async () => {
76	      const aliceReg = await runAgt(["users", "register", "alice"]);
77	      const aliceToken = parseJson(aliceReg.stdout).token;
78	      await runAgt(["users", "register", "bob"]);
79	
80	      const issueId = extractId(await runAgt(["create", "Test"]));
81	      await runAgt(["comments", "add", issueId, "--content", "@alice review"]);
82	
83	      // Get mention id and mark as read
84	      const listResult = await runAgt(["mentions", "list", "alice", "--include-reads"]);
85	      const mentionId = parseJson(listResult.stdout)[0].id;
86	      await runAgt(["mentions", "read", mentionId], undefined, {
87	        AGT_USER_TOKEN: aliceToken,
88	      });
89	
