      const listResult = await runAgt(["mentions", "list", "alice", "--include-reads"]);
      const mentionId = parseJson(listResult.stdout)[0].id;

      // Alice tries to use bob's token on alice's mention... wait, bob is wrong user here
      // Actually, alice was mentioned, so only alice can mark as read.
      // Let's have charlie try to mark alice's mention as read
      await runAgt(["users", "register", "charlie"]);
      const charlieReg = await runAgt(["users", "register", "charlie"]);
      // charlie already registered, use the first attempt
      // Actually let me just use alice as the wrong user scenario — bob is mentioned, alice tries
      // Wait, alice is the mentioned user. Let me use bob trying to mark alice's mention.
      const result = await runAgt(["mentions", "read", mentionId], undefined, {
        AGT_USER_TOKEN: bobToken,
      });
      assertError(result, "MENTION_ACCESS_DENIED", 21);
